[CmdletBinding()]
param([string]$SourceContainer='supabase_db_tradagora-bulk-e2e-baseline',[string]$TargetContainer='supabase_db_jarvis-desktop',[string]$SourceDatabase='postgres')
$ErrorActionPreference='Stop';$prefix='tradagora_initial_load17_';$database="${prefix}$PID`_$(Get-Date -Format 'yyyyMMddHHmmssfff')";$remote="/tmp/initial-load17-$PID";$dump="/tmp/initial-load17-$PID.dump";$hostDump=Join-Path ([IO.Path]::GetTempPath()) "tradagora-initial-load17-$PID.dump";$created=$false
function Invoke-Docker([string[]]$Arguments){$out=& docker @Arguments 2>&1;$code=$LASTEXITCODE;$out|Write-Output;if($code-ne 0){throw "docker falló ($code)"}}
function Guard([string]$Name){if($Name-notmatch '^tradagora_initial_load17_[0-9]+_[0-9]{17}$' -or $Name-eq$SourceDatabase){throw "Base temporal no autorizada: $Name"}}
function Psql([string]$User,[string]$File){Invoke-Docker @('exec',$TargetContainer,'psql','-U',$User,'-d',$database,'-X','-v','ON_ERROR_STOP=1','-f',"$remote/$File")}
try{
 Guard $database;$image=(& docker inspect --format '{{.Config.Image}}' $TargetContainer).Trim();if($LASTEXITCODE-ne 0-or$image-notmatch'supabase/postgres:17\.'){throw "Destino no compatible: $image"}
 Invoke-Docker @('exec',$TargetContainer,'mkdir','-p',$remote)
 $files=@{'platform.sql'='supabase/migrations/202610240001_admin_platform_transactional_writes.sql';'offer.sql'='supabase/migrations/202610240002_admin_offer_transactional_writes.sql';'coverage.sql'='supabase/migrations/202610270001_translation_editorial_coverage.sql';'source.sql'='supabase/migrations/202610270002_translation_field_source_language.sql';'groups.sql'='supabase/migrations/202610270003_translation_exact_group_proposals.sql';'fixtures.sql'='scripts/sql/translation-field-source-language-fixtures.sql';'acl.sql'='scripts/sql/translation-field-source-language-local-acl.sql';'precheck.sql'='scripts/sql/translation-initial-load-precheck.sql';'migration.sql'='supabase/migrations/202610270004_translation_initial_load_runner.sql';'refresh-patch.sql'='supabase/migrations/202610290001_translation_initial_load_refresh_batches.sql';'publication.sql'='supabase/migrations/202610290002_translation_initial_load_publication.sql';'platform-seed.sql'='supabase/migrations/202610290003_translation_initial_load_platform_seed.sql';'quarantine.sql'='supabase/migrations/202610290004_translation_initial_load_publish_quarantine.sql';'inline-quarantine.sql'='supabase/migrations/202610290005_translation_initial_load_inline_quarantine.sql';'close-pending.sql'='supabase/migrations/202610290006_translation_initial_load_close_pending.sql';'test.sql'='scripts/sql/translation-initial-load-postgres-test.sql';'close-pending-test.sql'='scripts/sql/translation-initial-load-close-pending-postgres-test.sql';'concurrency.sql'='scripts/sql/translation-initial-load-concurrency-test.sql';'postcheck.sql'='scripts/sql/translation-initial-load-postcheck.sql';'publication-postcheck.sql'='scripts/sql/translation-initial-load-publication-postcheck.sql';'platform-seed-postcheck.sql'='scripts/sql/translation-initial-load-platform-seed-postcheck.sql';'quarantine-postcheck.sql'='scripts/sql/translation-initial-load-publish-quarantine-postcheck.sql';'inline-quarantine-postcheck.sql'='scripts/sql/translation-initial-load-inline-quarantine-postcheck.sql';'close-pending-postcheck.sql'='scripts/sql/translation-initial-load-close-pending-postcheck.sql';'cleanup.sql'='scripts/sql/translation-initial-load-cleanup.sql';'cleanup-postcheck.sql'='scripts/sql/translation-initial-load-cleanup-postcheck.sql'}
 foreach($e in $files.GetEnumerator()){Invoke-Docker @('cp',(Join-Path $PSScriptRoot '..' $e.Value),"${TargetContainer}:$remote/$($e.Key)")}
 Invoke-Docker @('exec',$SourceContainer,'pg_dump','-U','postgres','-d',$SourceDatabase,'--format=c','--no-owner','--no-privileges','--exclude-table=vault.secrets','-f',$dump);Invoke-Docker @('cp',"${SourceContainer}:$dump",$hostDump);Invoke-Docker @('cp',$hostDump,"${TargetContainer}:$remote/source.dump")
 Invoke-Docker @('exec',$TargetContainer,'createdb','-U','postgres','-T','template0',$database);$created=$true;Invoke-Docker @('exec',$TargetContainer,'pg_restore','-U','postgres','-d',$database,'--no-owner','--no-privileges',"$remote/source.dump")
 Psql 'postgres' 'platform.sql';Psql 'postgres' 'offer.sql';Psql 'postgres' 'coverage.sql';Psql 'postgres' 'acl.sql';Psql 'postgres' 'fixtures.sql';Psql 'postgres' 'source.sql';Psql 'postgres' 'groups.sql';Psql 'postgres' 'precheck.sql';Psql 'postgres' 'migration.sql';Psql 'postgres' 'refresh-patch.sql';Psql 'postgres' 'publication.sql';Psql 'postgres' 'platform-seed.sql';Psql 'postgres' 'quarantine.sql';Psql 'postgres' 'inline-quarantine.sql';Psql 'postgres' 'close-pending.sql';Psql 'supabase_admin' 'test.sql';Psql 'supabase_admin' 'close-pending-test.sql';Psql 'supabase_admin' 'concurrency.sql';Psql 'postgres' 'postcheck.sql';Psql 'postgres' 'publication-postcheck.sql';Psql 'postgres' 'platform-seed-postcheck.sql';Psql 'postgres' 'quarantine-postcheck.sql';Psql 'postgres' 'inline-quarantine-postcheck.sql';Psql 'postgres' 'close-pending-postcheck.sql';Psql 'postgres' 'cleanup.sql';Psql 'postgres' 'cleanup-postcheck.sql'
 Write-Host "PASS PostgreSQL 17 aislado: $database ($image)"
}finally{
 if($created){Guard $database;Invoke-Docker @('exec',$TargetContainer,'psql','-U','postgres','-d',$SourceDatabase,'-X','-v','ON_ERROR_STOP=1','-c',"select pg_terminate_backend(pid) from pg_stat_activity where datname='$database' and pid<>pg_backend_pid();");Invoke-Docker @('exec',$TargetContainer,'dropdb','-U','postgres','--if-exists',$database)}
 & docker exec $SourceContainer rm -f $dump|Out-Null;& docker exec $TargetContainer rm -rf $remote|Out-Null;if(Test-Path -LiteralPath $hostDump){Remove-Item -LiteralPath $hostDump -Force}
 if($created){$left=(& docker exec $TargetContainer psql -U postgres -d $SourceDatabase -X -Atc "select count(*) from pg_database where datname='$database'").Trim();if($left-ne'0'){throw "Base temporal persistió: $database"}}
}
